-- RANGA V1 (v2.0.0): CSE scope, five resource categories, developer role + RLS, search updates.
-- Equivalent to manual-sql 001 + 002 + 004 (in that order). Catalogue seeding (003), the destructive cleanup (005) and
-- validation (006) stay manual on purpose. Generated by scripts/build-migration.sh — do not edit by hand.

-- >>>>>>>>>> 001_schema.sql
-- ============================================================================
-- RANGA 001 — Schema (additive, idempotent)
--
-- * Creates any missing base tables (fresh database) — existing tables are untouched.
-- * Adds new columns, constraints and indexes only with IF NOT EXISTS guards.
-- * Never drops tables or deletes rows. Constraints replaced on public.resources:
--     - resource_type CHECK: narrowed to the five V1 categories (added NOT VALID so existing legacy rows
--       do not block this script; 005_v1_cleanup.sql converts them and re-adds the check validated)
--     - resources_link_types_have_url: removed (YouTube / external-link resources no longer exist)
--     - NEW resources_pyq_requires_year: question papers (pyq) must carry a plausible year; other
--       categories may leave academic_year NULL (NOT VALID = enforced for new/updated rows only)
-- Run order: 000 (optional) -> 001 -> 002 -> 003 -> 004 -> 005 (destructive cleanup, read it first) -> 006 (validate)
-- ============================================================================

create extension if not exists pgcrypto;
create extension if not exists pg_trgm;

-- ---------- helper: updated_at trigger ----------
create or replace function public.set_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- ---------- base tables (no-ops when they already exist) ----------
create table if not exists public.programmes (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  name text not null,
  degree text not null default 'B.Tech',
  created_at timestamptz not null default now()
);

create table if not exists public.schemes (
  id uuid primary key default gen_random_uuid(),
  programme_id uuid not null references public.programmes(id),
  code text not null,
  name text not null,
  created_at timestamptz not null default now(),
  unique (programme_id, code)
);

create table if not exists public.semesters (
  id uuid primary key default gen_random_uuid(),
  scheme_id uuid not null references public.schemes(id),
  semester_number smallint not null check (semester_number between 1 and 8),
  name text not null,
  unique (scheme_id, semester_number)
);

create table if not exists public.subjects (
  id uuid primary key default gen_random_uuid(),
  semester_id uuid not null references public.semesters(id),
  code text not null,
  name text not null,
  created_at timestamptz not null default now(),
  unique (semester_id, code)
);

create table if not exists public.resources (
  id uuid primary key default gen_random_uuid(),
  subject_id uuid references public.subjects(id),
  title text not null,
  description text,
  resource_type text not null default 'other',
  academic_year integer,
  exam_session text,
  file_key text,
  external_url text,
  status text not null default 'draft' check (status in ('draft', 'published', 'archived')),
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check ((file_key is not null and external_url is null) or (file_key is null and external_url is not null))
);

-- ---------- programmes ----------
alter table public.programmes add column if not exists short_name text;
alter table public.programmes add column if not exists curriculum_group_2024 text;
alter table public.programmes add column if not exists sort_order integer;
alter table public.programmes add column if not exists is_active boolean not null default true;

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'programmes_curriculum_group_2024_check') then
    alter table public.programmes add constraint programmes_curriculum_group_2024_check
      check (curriculum_group_2024 is null or curriculum_group_2024 in ('A', 'B', 'C', 'D'));
  end if;
end $$;

-- ---------- schemes ----------
alter table public.schemes add column if not exists source_url text;
alter table public.schemes add column if not exists notes text;
alter table public.schemes add column if not exists verification_status text not null default 'needs_review';

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'schemes_verification_status_check') then
    alter table public.schemes add constraint schemes_verification_status_check
      check (verification_status in ('verified_official', 'verified_secondary', 'needs_review'));
  end if;
end $$;

-- ---------- courses: one canonical row per official course code ----------
create table if not exists public.courses (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  name text not null,
  course_type text,          -- theory | lab | workshop | project | seminar | elective | other
  course_category text,      -- BSC, ESC, PCC, PEC, MNC ... as printed by KTU
  credits numeric(3,1),
  ltp text,                  -- L-T-P (2019) or L-T-P-R (2024), as printed
  notes text,
  source_url text,
  verification_status text not null default 'needs_review'
    check (verification_status in ('verified_official', 'verified_secondary', 'needs_review')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ---------- subjects (an offering of a course in a given semester) ----------
-- course_type / course_category / credits already exist in the live database; these are no-ops there.
alter table public.subjects add column if not exists course_id uuid references public.courses(id);
alter table public.subjects add column if not exists course_type text;
alter table public.subjects add column if not exists course_category text;
alter table public.subjects add column if not exists credits numeric(3,1);
alter table public.subjects add column if not exists course_slot text;
alter table public.subjects add column if not exists source_url text;
alter table public.subjects add column if not exists verification_status text not null default 'needs_review';
alter table public.subjects add column if not exists sort_order integer;
alter table public.subjects add column if not exists updated_at timestamptz not null default now();

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'subjects_verification_status_check') then
    alter table public.subjects add constraint subjects_verification_status_check
      check (verification_status in ('verified_official', 'verified_secondary', 'needs_review'));
  end if;
end $$;

-- Back-fill: turn pre-existing subject rows into canonical courses (flagged needs_review,
-- because their origin is unknown) and link them. Existing data is not modified.
insert into public.courses (code, name, course_type, course_category, credits, verification_status)
select distinct on (s.code) s.code, s.name, s.course_type, s.course_category, s.credits, 'needs_review'
from public.subjects s
order by s.code, s.created_at
on conflict (code) do nothing;

update public.subjects s
set course_id = c.id
from public.courses c
where s.course_id is null and c.code = s.code;

-- ---------- resources: richer metadata ----------
alter table public.resources add column if not exists exam_type text;
alter table public.resources add column if not exists file_name text;
alter table public.resources add column if not exists file_size_bytes bigint;
alter table public.resources add column if not exists mime_type text;
alter table public.resources add column if not exists sha256 text;      -- duplicate detection for uploaded files
alter table public.resources add column if not exists published_at timestamptz;

do $$ begin
  -- five V1 categories (NOT VALID: legacy rows are converted by 005, which then validates)
  if exists (select 1 from pg_constraint
             where conrelid = 'public.resources'::regclass and conname = 'resources_resource_type_check') then
    alter table public.resources drop constraint resources_resource_type_check;
  end if;
  alter table public.resources add constraint resources_resource_type_check
    check (resource_type in ('pyq', 'notes', 'study_material', 'lab', 'other')) not valid;

  if not exists (select 1 from pg_constraint where conname = 'resources_exam_type_check') then
    alter table public.resources add constraint resources_exam_type_check
      check (exam_type is null or exam_type in ('end_semester', 'supplementary', 'series_test', 'model', 'other'));
  end if;

  -- links are no longer a user-facing resource type
  if exists (select 1 from pg_constraint where conname = 'resources_link_types_have_url') then
    alter table public.resources drop constraint resources_link_types_have_url;
  end if;

  -- year: required for question papers, optional (NULL) for everything else
  if not exists (select 1 from pg_constraint where conname = 'resources_pyq_requires_year') then
    alter table public.resources add constraint resources_pyq_requires_year
      check (resource_type <> 'pyq' or (academic_year is not null and academic_year between 2000 and 2100)) not valid;
  end if;
end $$;

-- duplicate protection
create unique index if not exists resources_sha256_key
  on public.resources (sha256) where sha256 is not null;
drop index if exists public.resources_link_per_subject_key;   -- external links are no longer a resource type

-- ---------- updated_at triggers ----------
drop trigger if exists trg_resources_updated_at on public.resources;
create trigger trg_resources_updated_at before update on public.resources
  for each row execute function public.set_updated_at();
drop trigger if exists trg_subjects_updated_at on public.subjects;
create trigger trg_subjects_updated_at before update on public.subjects
  for each row execute function public.set_updated_at();
drop trigger if exists trg_courses_updated_at on public.courses;
create trigger trg_courses_updated_at before update on public.courses
  for each row execute function public.set_updated_at();

-- >>>>>>>>>> 002_permissions_and_rls.sql
-- ============================================================================
-- RANGA 002 — Permissions, developer role and Row Level Security (idempotent)
-- Depends on: 001_schema.sql
--
-- Model
--   * anon / authenticated can READ the catalogue and PUBLISHED resources.
--   * A "developer" is a Supabase Auth user whose id is listed in public.app_developers.
--     That table is invisible to the API; membership is checked by the SECURITY DEFINER function
--     public.is_developer(), which is what every write policy uses. There is no client-side flag.
--   * Developers may write the catalogue and update/delete resource rows through the API (RLS enforced).
--     Developers cannot INSERT resources through the API: uploads go through the `developer-resources`
--     Edge Function, which validates the PDF, writes to private storage and inserts with the service role.
--   * Everyone else has no write access whatsoever.
--
-- ADD A DEVELOPER (SQL editor, run as project owner — see README "Developer access"):
--   insert into public.app_developers (user_id, note)
--   select id, 'owner' from auth.users where email = 'you@example.com';
-- ============================================================================

-- ---------- developer allowlist ----------
create table if not exists public.app_developers (
  user_id uuid primary key references auth.users (id) on delete cascade,
  note text,
  created_at timestamptz not null default now()
);
alter table public.app_developers enable row level security;     -- no policies: unreachable through the API
revoke all on public.app_developers from anon, authenticated;

create or replace function public.is_developer()
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (select 1 from public.app_developers d where d.user_id = auth.uid())
$$;
revoke all on function public.is_developer() from public;
grant execute on function public.is_developer() to anon, authenticated;

-- ---------- RLS on ----------
alter table public.programmes enable row level security;
alter table public.schemes    enable row level security;
alter table public.semesters  enable row level security;
alter table public.subjects   enable row level security;
alter table public.courses    enable row level security;
alter table public.resources  enable row level security;

-- ---------- public read policies ----------
drop policy if exists "Public can read programmes" on public.programmes;
create policy "Public can read programmes" on public.programmes for select to anon, authenticated using (true);
drop policy if exists "Public can read schemes" on public.schemes;
create policy "Public can read schemes" on public.schemes for select to anon, authenticated using (true);
drop policy if exists "Public can read semesters" on public.semesters;
create policy "Public can read semesters" on public.semesters for select to anon, authenticated using (true);
drop policy if exists "Public can read subjects" on public.subjects;
create policy "Public can read subjects" on public.subjects for select to anon, authenticated using (true);
drop policy if exists "Public can read courses" on public.courses;
create policy "Public can read courses" on public.courses for select to anon, authenticated using (true);
drop policy if exists "Public can read published resources" on public.resources;
create policy "Public can read published resources" on public.resources for select to anon, authenticated
  using (status = 'published');

-- ---------- developer write policies ----------
drop policy if exists "Developers manage programmes" on public.programmes;
create policy "Developers manage programmes" on public.programmes for all to authenticated
  using (public.is_developer()) with check (public.is_developer());
drop policy if exists "Developers manage schemes" on public.schemes;
create policy "Developers manage schemes" on public.schemes for all to authenticated
  using (public.is_developer()) with check (public.is_developer());
drop policy if exists "Developers manage semesters" on public.semesters;
create policy "Developers manage semesters" on public.semesters for all to authenticated
  using (public.is_developer()) with check (public.is_developer());
drop policy if exists "Developers manage subjects" on public.subjects;
create policy "Developers manage subjects" on public.subjects for all to authenticated
  using (public.is_developer()) with check (public.is_developer());
drop policy if exists "Developers manage courses" on public.courses;
create policy "Developers manage courses" on public.courses for all to authenticated
  using (public.is_developer()) with check (public.is_developer());

drop policy if exists "Developers read all resources" on public.resources;
create policy "Developers read all resources" on public.resources for select to authenticated
  using (public.is_developer());
drop policy if exists "Developers update resources" on public.resources;
create policy "Developers update resources" on public.resources for update to authenticated
  using (public.is_developer()) with check (public.is_developer());
drop policy if exists "Developers delete resources" on public.resources;
create policy "Developers delete resources" on public.resources for delete to authenticated
  using (public.is_developer());

-- ---------- table privileges ----------
-- Start from nothing, then grant back. RLS above decides WHO may use each privilege.
revoke insert, update, delete, truncate on
  public.programmes, public.schemes, public.semesters, public.subjects, public.courses, public.resources
from anon, authenticated;

grant select on public.programmes, public.schemes, public.semesters, public.subjects, public.courses
  to anon, authenticated;
grant insert, update, delete on public.programmes, public.schemes, public.semesters, public.subjects, public.courses
  to authenticated;                                    -- usable only by developers (policies)

-- resources: expose everything EXCEPT file_key and sha256 (storage internals) via column grants.
revoke select on public.resources from anon, authenticated;
grant select (id, subject_id, title, description, resource_type, academic_year, exam_session,
              exam_type, file_name, file_size_bytes, mime_type, external_url, status, metadata,
              created_at, updated_at, published_at)
  on public.resources to anon, authenticated;
-- developers may edit descriptive fields and status; storage columns can only change via the Edge Function
grant update (title, description, resource_type, academic_year, exam_session, exam_type, status, published_at)
  on public.resources to authenticated;
grant delete on public.resources to authenticated;      -- row only; the Edge Function also removes the stored file

-- >>>>>>>>>> 004_search_and_indexes.sql
-- ============================================================================
-- RANGA 004 — Search indexes, the public resource view and search functions (idempotent)
-- Depends on: 001, 002 (003 is not required, but there is nothing to search without it)
-- ============================================================================

-- ---------- indexes ----------
create index if not exists idx_subjects_semester_order on public.subjects (semester_id, sort_order, code);
create index if not exists idx_subjects_course on public.subjects (course_id);
create index if not exists idx_resources_subject_status on public.resources (subject_id, status, resource_type);
create index if not exists idx_resources_published_recent on public.resources (created_at desc) where status = 'published';
drop index if exists public.idx_resources_year;
create index if not exists idx_resources_pyq_year on public.resources (academic_year desc, subject_id)
  where status = 'published' and resource_type = 'pyq';
create index if not exists idx_resources_type_recent on public.resources (resource_type, created_at desc)
  where status = 'published';
create index if not exists idx_resources_exam_session_trgm on public.resources using gin (exam_session gin_trgm_ops);
create index if not exists idx_subjects_code_nospace on public.subjects (lower(replace(code, ' ', '')));

create index if not exists idx_subjects_name_trgm on public.subjects using gin (name gin_trgm_ops);
create index if not exists idx_subjects_code_trgm on public.subjects using gin (code gin_trgm_ops);
create index if not exists idx_resources_title_trgm on public.resources using gin (title gin_trgm_ops);
create index if not exists idx_programmes_name_trgm on public.programmes using gin (name gin_trgm_ops);

-- ---------- public resource view (published only, no storage keys) ----------
-- security_invoker: the caller's RLS and column grants apply, so file_key is never reachable.
create or replace view public.resource_catalogue
with (security_invoker = true) as
select
  r.id, r.title, r.description, r.resource_type, r.academic_year, r.exam_session, r.exam_type,
  r.file_name, r.file_size_bytes, r.mime_type, r.external_url,
  (r.external_url is null) as has_file,     -- the XOR check guarantees: no link => stored file
  r.created_at,
  s.id as subject_id, s.code as subject_code, s.name as subject_name,
  sem.id as semester_id, sem.semester_number,
  sch.id as scheme_id, sch.code as scheme_code, sch.name as scheme_name,
  p.id as programme_id, p.code as programme_code, p.name as programme_name
from public.resources r
left join public.subjects  s   on s.id = r.subject_id
left join public.semesters sem on sem.id = s.semester_id
left join public.schemes   sch on sch.id = sem.scheme_id
left join public.programmes p  on p.id = sch.programme_id
where r.status = 'published';

grant select on public.resource_catalogue to anon, authenticated;

-- ---------- helper: escape LIKE wildcards in user input ----------
create or replace function public.ranga_like_pattern(q text)
returns text language sql immutable as $$
  select '%' || replace(replace(replace(trim(coalesce(q, '')), '\', '\\'), '%', '\%'), '_', '\_') || '%'
$$;

-- ---------- search_resources ----------
create or replace function public.search_resources(
  q text default null,
  p_programme text default null,      -- programme CODE, e.g. 'CSE'
  p_scheme text default null,         -- scheme CODE, e.g. '2019'
  p_semester smallint default null,
  p_type text default null,
  p_year integer default null,
  p_limit integer default 20,
  p_offset integer default 0
)
returns table (
  id uuid, title text, description text, resource_type text, academic_year integer,
  exam_session text, exam_type text, file_name text, file_size_bytes bigint, external_url text,
  has_file boolean, created_at timestamptz,
  subject_id uuid, subject_code text, subject_name text, semester_number smallint,
  scheme_id uuid, scheme_code text, scheme_name text, programme_id uuid, programme_code text,
  programme_name text, total_count bigint
)
language sql stable security invoker set search_path = public, extensions
as $$
  with pat as (select public.ranga_like_pattern(q) as p, (trim(coalesce(q, '')) = '') as blank)
  select c.id, c.title, c.description, c.resource_type, c.academic_year, c.exam_session, c.exam_type,
         c.file_name, c.file_size_bytes, c.external_url, c.has_file, c.created_at,
         c.subject_id, c.subject_code, c.subject_name, c.semester_number,
         c.scheme_id, c.scheme_code, c.scheme_name, c.programme_id, c.programme_code,
         c.programme_name, count(*) over () as total_count
  from public.resource_catalogue c, pat
  where (pat.blank or c.title ilike pat.p or c.description ilike pat.p or c.subject_code ilike pat.p
         or replace(lower(c.subject_code), ' ', '') like replace(lower(pat.p), ' ', '')
         or c.subject_name ilike pat.p or c.programme_name ilike pat.p or c.programme_code ilike pat.p
         or c.exam_session ilike pat.p
         or (c.academic_year is not null and c.academic_year::text = trim(coalesce(q, ''))))
    and (p_programme is null or c.programme_code = p_programme)
    and (p_scheme    is null or c.scheme_code = p_scheme)
    and (p_semester  is null or c.semester_number = p_semester)
    and (p_type      is null or c.resource_type = p_type)
    and (p_year      is null or (c.resource_type = 'pyq' and c.academic_year = p_year))
  order by c.created_at desc, c.id
  limit least(greatest(p_limit, 1), 50) offset greatest(p_offset, 0)
$$;

-- ---------- search_subjects ----------
create or replace function public.search_subjects(
  q text default null,
  p_programme text default null,      -- programme CODE
  p_scheme text default null,         -- scheme CODE
  p_semester smallint default null,
  p_limit integer default 20,
  p_offset integer default 0
)
returns table (
  id uuid, code text, name text, course_type text, course_category text, credits numeric,
  verification_status text, semester_id uuid, semester_number smallint,
  scheme_id uuid, scheme_code text, scheme_name text, programme_id uuid, programme_code text,
  programme_name text, resource_count bigint, total_count bigint
)
language sql stable security invoker set search_path = public, extensions
as $$
  with pat as (select public.ranga_like_pattern(q) as p, (trim(coalesce(q, '')) = '') as blank)
  select s.id, s.code, s.name, s.course_type, s.course_category, s.credits, s.verification_status,
         sem.id, sem.semester_number, sch.id, sch.code, sch.name, p.id, p.code, p.name,
         (select count(*) from public.resources r where r.subject_id = s.id and r.status = 'published'),
         count(*) over ()
  from public.subjects s
  join public.semesters sem on sem.id = s.semester_id
  join public.schemes sch on sch.id = sem.scheme_id
  join public.programmes p on p.id = sch.programme_id, pat
  where (pat.blank or s.code ilike pat.p or replace(lower(s.code), ' ', '') like replace(lower(pat.p), ' ', '')
         or s.name ilike pat.p or p.name ilike pat.p or p.code ilike pat.p)
    and (p_programme is null or p.code = p_programme)
    and (p_scheme    is null or sch.code = p_scheme)
    and (p_semester  is null or sem.semester_number = p_semester)
  order by p.sort_order nulls last, p.name, sch.code, sem.semester_number, s.sort_order nulls last, s.code
  limit least(greatest(p_limit, 1), 50) offset greatest(p_offset, 0)
$$;

-- ---------- semester_subjects: subjects of one semester with real resource counts ----------
create or replace function public.semester_subjects(p_semester uuid)
returns table (
  id uuid, code text, name text, course_type text, course_category text, credits numeric,
  course_slot text, verification_status text, resource_count bigint
)
language sql stable security invoker set search_path = public
as $$
  select s.id, s.code, s.name, s.course_type, s.course_category, s.credits, s.course_slot,
         s.verification_status,
         (select count(*) from public.resources r where r.subject_id = s.id and r.status = 'published')
  from public.subjects s
  where s.semester_id = p_semester
  order by s.sort_order nulls last, s.code
$$;

-- ---------- resource_type_counts: real numbers for the home screen ----------
create or replace function public.resource_type_counts()
returns table (resource_type text, total bigint)
language sql stable security invoker set search_path = public
as $$
  select r.resource_type, count(*) from public.resources r where r.status = 'published' group by r.resource_type
$$;

grant execute on function public.search_resources(text, text, text, smallint, text, integer, integer, integer) to anon, authenticated;
grant execute on function public.search_subjects(text, text, text, smallint, integer, integer) to anon, authenticated;
-- ---------- resource_years: distinct years that have published QUESTION PAPERS (year is a pyq-only field) ----------
create or replace function public.resource_years()
returns table (academic_year integer)
language sql stable security invoker set search_path = public
as $$
  select distinct r.academic_year from public.resources r
  where r.status = 'published' and r.resource_type = 'pyq' and r.academic_year is not null order by 1 desc
$$;
grant execute on function public.resource_years() to anon, authenticated;

grant execute on function public.semester_subjects(uuid) to anon, authenticated;
grant execute on function public.resource_type_counts() to anon, authenticated;

